package main

import "fmt"

func main() {
	buf := make(chan int, 2)
	dropped := 0
	for i := 1; i <= 5; i++ {
		select {
		case buf <- i:
		default:
			dropped++ // the buffer is full, so skip instead of waiting
		}
	}
	close(buf)
	var kept []int
	for v := range buf {
		kept = append(kept, v)
	}
	fmt.Println("kept:", kept)
	fmt.Println("dropped:", dropped)

	empty := make(chan int)
	select {
	case v := <-empty:
		fmt.Println("got", v)
	default:
		fmt.Println("no value ready")
	}
}

