package main

import (
	"fmt"
	"sort"
	"sync"
)

const (
	NumJobs    = 6
	NumWorkers = 3
)

func worker(jobs <-chan int, results chan<- int, wg *sync.WaitGroup) {
	defer wg.Done()
	for n := range jobs {
		results <- n * n
	}
}

func main() {
	jobs := make(chan int, NumJobs)
	results := make(chan int, NumJobs)
	var wg sync.WaitGroup
	for w := 0; w < NumWorkers; w++ {
		wg.Add(1)
		go worker(jobs, results, &wg)
	}
	for n := 1; n <= NumJobs; n++ {
		jobs <- n
	}
	close(jobs) // lets every worker's range loop end
	go func() {
		wg.Wait()
		close(results)
	}()
	var squares []int
	for sq := range results {
		squares = append(squares, sq)
	}
	sort.Ints(squares)
	fmt.Println(squares)
}

