package main

import (
	"fmt"
	"sort"
	"sync"
)

const NumWorkers = 2

func worker(jobs <-chan string, results chan<- string, wg *sync.WaitGroup) {
	defer wg.Done()
	for w := range jobs {
		results <- fmt.Sprintf("%s:%d", w, len(w))
	}
}

func main() {
	words := []string{"select", "go", "channel", "pool", "done"}
	jobs := make(chan string, len(words))
	results := make(chan string, len(words))
	var wg sync.WaitGroup
	for i := 0; i < NumWorkers; i++ {
		wg.Add(1)
		go worker(jobs, results, &wg)
	}
	for _, w := range words {
		jobs <- w
	}
	close(jobs)
	go func() {
		wg.Wait()
		close(results)
	}()
	var lines []string
	for line := range results {
		lines = append(lines, line)
	}
	sort.Strings(lines)
	fmt.Println(lines)
}
